Ext.define('BNK.view.Budget.exp.ExpNteRcpt51MViewController', {
    extend: 'Ext.app.ViewController',
    alias: 'controller.ExpNteRcpt51MViewController',

    config: {
        viewId: 'ExpNteRcpt51M'
    },

    /* 팝업 닫기 */
    onClose: function(button, e, eOpts) {
        this.getView().close();
    },

    /* 매출전표 팝업 */
    initialize: function(component, eOpts) {
        var me = this,
            vm = me.getViewModel(),
            refs = me.getReferences(),
            etcReceipt = component.initialConfig.etcReceipt,
            records = component.initialConfig.records;

        for(var key in records){
            if(!records[key] || records[key] === ' '){
                records[key] = '-';
            }
        }

        if(records.cdno) cdnoText = records.cdno.substring(0, 4)+'-'+records.cdno.substring(4, 8)+'-'+records.cdno.substring(8, 12)+'-'+records.cdno.substring(12, 16); // 카드번호
        if(!records.trnsDvnm || records.trnsDvnm === ' ') records.trnsDvnm = '-';
        if(!records.mcAddr)   records.mcAddr = '-';
        if(!records.mcNo)     records.mcNo = '-';
        if(!records.mcTlno || records.mcTlno === ' ')   records.mcTlno = '-';

        if(records.mcNm && records.mcNm.length > 10) records.mcNmText = records.mcNm.substring(0, 10) + '...'; // + '<br>' + records.mcNm.substring(10, records.mcNm.length);
        else records.mcNmText = records.mcNm;

        if(records.mcAddr && records.mcAddr.length > 10) records.mcAddrText = records.mcAddr.substring(0, 10) + '...'; // + '<br>' + records.mcAddr.substring(10, records.mcAddr.length);
        else records.mcAddrText = records.mcAddr;

        // trnsDvnm // 결제방법
        // mcAddr // 가맹점주소
        // mcNo // 가맹점번호
        // mcTlno // 연락처

        vm.set('records', records);
        vm.set('etcReceipt', etcReceipt);

        this.getView().setAlwaysOnTop(true);

    }

});